 "Alte Prüfung": "Ancien examen",
 "Alte Prüfungen hochladen (PDF/Foto) und daraus Zwillingsprüfungen erstellen ist eine Pro-Funktion.": "Uploader d'anciennes épreuves (PDF/photo) et créer des épreuves jumelles, c’est une fonction Pro.",
 "Anfrage abgelehnt": "Demande refusée",
 "Aufnahmeprüfung Berufsmaturitätsschule. Stoff bis und mit 1. Semester 3. Sek. Bestanden mit Schnitt ≥ 4.0, Mathe zählt oft doppelt.": "Épreuve d’admission à l’école de maturité professionnelle. Programme jusqu’au 1er semestre de la 3e secondaire. Réussi avec une moyenne ≥ 4.0, les maths comptent souvent double.",
 "BMS Zürich: Aufnahmeprüfung & Musterprüfungen": "BMS Zurich : épreuve d’admission & épreuves modèles",
 "Basisprüfung nach dem #. Studienjahr (z. B. Analysis, Lineare Algebra, Physik, Informatik). Beweise, Rechenaufgaben und Konzeptfragen auf Hochschulniveau.": "Épreuve de base après la #e année d’études (ex. Analyse, Algèbre linéaire, Physique, Informatique). Preuves, exercices et questions conceptuelles de niveau universitaire.",
 "Basisprüfung nach dem 1. Studienjahr (z. B. Analysis, Lineare Algebra, Physik, Informatik). Beweise, Rechenaufgaben und Konzeptfragen auf Hochschulniveau.": "Épreuve de base après la 1re année d’études (ex. Analyse, Algèbre linéaire, Physique, Informatique). Preuves, exercices et questions conceptuelles de niveau universitaire.",
 "Beispiel: BMP Mathematik 2024 (KV Zürich, PDF)": "Exemple : BMP Mathématiques 2024 (KV Zurich, PDF)",
 "Berufsmaturitätsprüfung nach Rahmenlehrplan BM 2012. Typisch 120 min, ca. 10 Aufgaben mit total 100 Punkten, nicht programmierbarer Taschenrechner + Formelsammlung.": "Épreuve de maturité professionnelle selon le programme-cadre BM 2012. Typiquement 120 min, ~10 tâches pour 100 points, calculatrice non programmable + recueil de formules.",
 "Blitz-Paare": "Paires éclair",
 "Blockierte Personen": "Personnes bloquées",
 "Blockierte Personen sehen dein Profil und deine Sessions nicht.": "Les personnes bloquées ne voient pas ton profil et tes sessions.",
 "Blockierung aufgehoben": "Blocage levé",
 "Brain Jump": "Brain Jump",
 "Brainy erstellt": "Brainy crée",
 "Combo von # = höherer Multiplikator · Fehler kosten # Sekunden": "Combo de # = multiplicateur plus élevé · Erreur coûte # secondes",
 "Countdown wie echt, Lösungen erst am Schluss": "Compte à rebours comme réel, solutions seulement à la fin",
 "Das dauert ca. #–# Sekunden – Brainy rechnet jede Lösung nach.": "Ça dure env. #–# secondes – Brainy calcule chaque solution après.",
 "Dein Profil ist öffentlich – alle können dir direkt folgen.": "Ton profil est public – tout le monde peut te suivre directement.",
 "Deine Lernpläne": "Tes plans d’apprentissage",
 "Demo-Modus: Beispielaufgaben aus der Brained-Fragenbank.": "Mode démo : exemples d’exercices de la banque de questions Brained.",
 "Der Plan und seine Sessions im Kalender werden entfernt. Deine bisherigen Lernsessions bleiben.": "Le plan et ses sessions sont supprimés du calendrier. Tes sessions précédentes restent.",
 "Deutsch (Duden erlaubt): Textverständnis eines Sachtexts, Grammatik und Sprachbetrachtung (Satzglieder, Konjunktiv, indirekte Rede, Kommaregeln) und ein Aufsatz/argumentativer Text.": "Allemand (Duden autorisé) : compréhension d’un texte informatif, grammaire et analyse linguistique (compléments, subjonctif, discours indirect, règles de ponctuation) et rédaction/texte argumentatif.",
 "Deutsch BMP: Erörterung/Interpretation zu einem literarischen oder pragmatischen Text, Textanalyse, Sprachreflexion.": "Allemand BMP : discussion/interprétation d’un texte littéraire ou pragmatique, analyse de texte, réflexion linguistique.",
 "Deutsch Matura: Aufsatz (Erörterung, Interpretation eines Gedichts/Prosatexts, Essay) – Aufgaben mit Textbezug und Begründung.": "Allemand Maturité : rédaction (discussion, interprétation d’un poème ou texte en prose, essai) – exercices avec référence au texte et justification.",
 "Deutsch · Prüfung Fr, #. Oktober · noch # Tage": "Allemand · examen ven, #. octobre · encore # jours",
 "Deutsch: Textverständnis zu einem Sachtext oder einer Erzählung (Fragen zum Inhalt, zur Absicht, zu Wortbedeutungen), Sprachbetrachtung (Wortarten, Satzglieder, Zeitformen, Rechtschreibung, Zeichensetzung) und ein kurzer Aufsatz/Schreibauftrag.": "Allemand : compréhension d’un texte informatif ou narratif (questions sur le contenu, l’intention, le sens des mots), analyse linguistique (catégories grammaticales, fonctions, temps, orthographe, ponctuation) et courte rédaction/consigne d’écriture.",
 "Di, #. Oktober · # min": "Di, #. octobre · # min",
 "Do, #. Oktober · # min": "Do, #. octobre · # min",
 "Ein Rechteck ist # cm lang und hat den …": "Un rectangle mesure # cm de long et a le …",
 "Englisch (Niveau A2–B1): Reading comprehension, Grammar (tenses, conditionals, passive, reported speech), Vocabulary in context, kurzer Schreibauftrag.": "Anglais (Niveau A2–B1) : compréhension écrite, grammaire (temps, conditionnels, passif, discours indirect), vocabulaire en contexte, petite tâche d’écriture.",
 "Englisch BMP (B2): Reading, Use of English, Writing (essay/formal letter), Literature/Culture.": "Anglais BMP (B2) : lecture, usage de l’anglais, écriture (essai/lettre formelle), littérature/culture.",
 "Entblocken ist still – die Person erfährt nichts davon. Folgen müsst ihr euch danach neu.": "Débloquer est discret – la personne n’en apprend rien. Vous devez vous re‑suivre après.",
 "Erklär Brainy ein Thema – schriftlich oder per Sprachmemo 🎤. Brainy stellt naive Fragen, bis jede Lücke sichtbar ist, und bewertet dich am Ende.": "Explique un sujet à Brainy – par écrit ou via mémo vocal 🎤. Brainy pose des questions naïves jusqu’à ce que chaque trou soit visible, et te note à la fin.",
 "Erklär ein Thema – auch per Sprachmemo 🎤. Brainy findet deine Lücken.": "Explique un sujet – même via mémo vocal 🎤. Brainy trouve tes lacunes.",
 "Erledigt": "Fait",
 "Finde Frage und Antwort – so viele Paare wie möglich in # Sekunden.": "Trouve question et réponse – le plus de paires possible en # secondes.",
 "Folgeanfragen": "Demandes de suivi",
 "Folgen nur mit Anfrage": "Suivre uniquement sur demande",
 "Mathematik (# min, ohne Taschenrechner): Grundoperationen und Kopfrechnen, Brüche/Dezimalzahlen, Masseinheiten umrechnen, Proportionalität und Dreisatz, Geometrie (Flächen, Umfang, Winkel, Körper, Konstruktion beschreiben), Knobel- und Textaufgaben aus dem Alltag. Lösungsweg gibt Teilpunkte. Viele mehrteilige Aufgaben mit steigender Schwierigkeit.": "Mathématiques (# min, sans calculatrice) : opérations de base et calcul mental, fractions/nombres décimaux, conversion d'unités, proportionnalité et règle de trois, géométrie (aires, périmètre, angles, solides, description de la construction), énigmes et problèmes de texte du quotidien. Le chemin de solution donne des points partiels. Beaucoup de tâches à plusieurs parties avec difficulté croissante.",
