 "Coenzym": "Co‑enzyme",
 "Dabei wird": "Cela libère",
 "Dabei wird Energie freigesetzt, und ein Teil davon wird in ATP gespeichert.": "De l’énergie est libérée, une partie étant stockée sous forme d’ATP.",
 "Dabei wird ein Molekül Glucose mit sechs Kohlenstoffatomen in zwei Moleküle Pyruvat mit je drei Kohlenstoffatomen gespalten. Der übrig bleibende Rest mit zwei Kohlenstoffatomen verbindet sich mit dem Coenzym A zum Acetyl-CoA.": "Une molécule de glucose à six carbones se scinde en deux molécules de pyruvate à trois carbones chacune. Le résidu à deux carbones se combine avec le co‑enzyme A pour former l’acétyl‑CoA.",
 "Danke dir! Jetzt bist du dran mit den Fragen.": "Merci ! C’est à ton tour avec les questions.",
 "Danke für deine Erklärung.": "Merci pour ton explication.",
 "Das": "Le",
 "Das Bild konnte nicht geladen werden.": "L’image n’a pas pu être chargée.",
 "Das Material dieses Kurses fehlt auf diesem Gerät – bitte neu hochladen.": "Le matériel de ce cours manque sur cet appareil – merci de le re‑téléverser.",
 "Das Pyruvat gelangt nun aus dem Zellplasma in die ____, die man oft als Kraftwerke der Zelle bezeichnet. Der übrig bleibende Rest mit zwei ____ verbindet sich mit dem Coenzym A zum Acetyl-CoA.": "Le pyruvate passe maintenant du cytoplasme à la ____, souvent appelée la centrale énergétique de la cellule. Le résidu restant avec deux ____ se lie au co‑enzyme A pour former l’acétyl‑CoA.",
 "Das Wichtigste": "L’essentiel",
 "Das ____ ist die Eintrittsstelle für den nächsten Abschnitt. Sauerstoff wird in diesem Abschnitt noch nicht verbraucht, doch der Zyklus steht still, wenn die ____ keinen Sauerstoff erhält.": "Le ____ est le point d’entrée du prochain segment. L’oxygène n’est pas encore consommé ici, mais le cycle s’arrête si le ____ ne reçoit pas d’oxygène.",
 "Das ____ und das ____.": "Le ____ et le ____.",
 "Das dauert einen Moment. Du kannst die App offen lassen.": "Ça prend un instant. Tu peux laisser l’app ouverte.",
 "Das erste Wort steht dafür, dass dem Pyruvat Wasserstoff entzogen wird, das zweite dafür, dass eine Carboxylgruppe als Kohlenstoffdioxid abgespalten wird. Dabei werden zwei Moleküle Kohlenstoffdioxid abgespalten, und am Ende des Kreislaufs steht wieder Oxalacetat bereit, sodass der Zyklus von vorn beginnen kann.": "Le premier mot indique que le pyruvate perd de l’hydrogène, le second que le groupe carboxyle est libéré comme CO₂. Deux molécules de CO₂ sont ainsi détachées, et à la fin du cycle l’oxaloacétate est de nouveau disponible pour redémarrer le cycle.",
 "Das grosse Ziel wartet": "Le grand objectif t’attend",
 "Das hat nicht geklappt": "Ça n’a pas fonctionné",
 "Das sitzt noch nicht": "Ce n’est pas encore en place",
 "Datei entfernen": "Supprimer le fichier",
 "Decarboxylierung": "Décarboxylation",
 "Dein Fortschritt in diesem Baustein geht dabei verloren.": "Ta progression dans ce module sera perdue.",
