 "Eddy (Deutsch (Deutschland))": "Eddy (Allemand (Allemagne))",
 "Eigener Text": "Texte personnel",
 "Ein Molekül Glucose reagiert mit sechs Molekülen Sauerstoff zu sechs Molekülen Decarboxylierung und sechs Molekülen Wasser.": "Une molécule de glucose réagit avec six molécules d’oxygène pour former six molécules de décarboxylation et six molécules d’eau.",
 "Ein Molekül Glucose reagiert mit sechs Molekülen Sauerstoff zu sechs Molekülen Intermembranraum und sechs Molekülen Wasser.": "Une molécule de glucose réagit avec six molécules d’oxygène pour former six molécules d’espace intermembranaire et six molécules d’eau.",
 "Ein Molekül Glucose reagiert mit sechs Molekülen Sauerstoff zu sechs Molekülen Kohlenstoffdioxid und sechs Molekülen Wasser.": "Une molécule de glucose réagit avec six molécules d’oxygène pour former six molécules de dioxyde de carbone et six molécules d’eau.",
 "Ein Molekül Glucose reagiert mit sechs Molekülen Sauerstoff zu sechs Molekülen Kohlenstoffdioxid und sechs Molekülen Wasser. Dabei wird Energie freigesetzt, und ein Teil davon wird in ATP gespeichert. Der Rest geht als Wärme verloren, was erklärt, warum unser Körper warm bleibt. In Wirklichkeit läuft die Zellatmung nicht in einem Schritt ab.": "Une molécule de glucose réagit avec six molécules d’oxygène pour former six molécules de dioxyde de carbone et six molécules d’eau. L’énergie libérée est partiellement stockée sous forme d’ATP, le reste se dissipe en chaleur, ce qui explique pourquoi notre corps reste chaud. En réalité, la respiration cellulaire ne se déroule pas en une seule étape.",
 "Ein Molekül Glucose reagiert mit sechs Molekülen Sauerstoff zu sechs Molekülen Stoffwechselweg und sechs Molekülen Wasser.": "Une molécule de glucose réagit avec six molécules d’oxygène pour former six molécules de voie métabolique et six molécules d’eau.",
 "Ein Molekül Glucose reagiert mit sechs Molekülen Sauerstoff zu sechs Molekülen … und sechs Molekülen Wasser.": "Une molécule de glucose réagit avec six molécules d’oxygène pour former six molécules de … et six molécules d’eau.",
