 "Ergänze: «Ein Molekül Glucose reagiert mit sechs Molekülen Sauerstoff zu sechs Molekülen ___ und sechs Molekülen Wasser.»": "Complète : «Une molécule de glucose réagit avec six molécules d’oxygène pour former six molécules de ___ et six molécules d’eau.»",
 "Ergänze: «Stattdessen zerlegt die Zelle den Zucker in vier aufeinanderfolgenden Abschnitten: die Glykolyse, die oxidative ___, der Citratzyklus und die Atmungskette.»": "Complète : «Au lieu de cela, la cellule décompose le sucre en quatre étapes consécutives : la glycolyse, l’___ oxydatif, le cycle de l’acide citrique et la chaîne respiratoire.»",
 "Ergänze: «Stattdessen zerlegt die Zelle den Zucker in vier aufeinanderfolgenden Abschnitt…": "Complète : «Au lieu de cela, la cellule décompose le sucre en quatre étapes consécutives…",
 "Ergänze: «Wenn eine Phosphatgruppe von ATP abgespalten wird, entsteht ADP, und dabei wird ___ frei, die die Zelle für ihre Arbeit nutzen kann.»": "Complète : «Quand un groupe phosphate est détaché de l’ATP, on obtient de l’ADP et ___ est libéré, que la cellule peut utiliser pour son travail.»",
 "Ergänze: «Wenn eine Phosphatgruppe von ATP abgespalten wird, entsteht ADP, und dabei wird…": "Complète : «Quand un groupe phosphate est détaché de l’ATP, on obtient de l’ADP et…",
