 "Falsch: Im Text steht «Decarboxylierung», nicht «Kohlenstoffatomen».": "Faux : le texte indique « Decarboxylierung », pas « atome de carbone ».",
 "Falsch: Im Text steht «Decarboxylierung», nicht «Kohlenstoffdioxid».": "Faux : le texte indique « Decarboxylierung », pas « dioxyde de carbone ».",
