 "Fehlerkurs": "Cours d’erreurs",
 "Fettsäuren werden in Stücke mit je zwei ____ zerlegt, die als Acetyl-CoA direkt in den Citratzyklus eintreten. In unseren Muskelzellen entsteht auf diese Weise Milchsäure, in Hefezellen entstehen Ethanol und ____.": "Les acides gras sont découpés en morceaux de deux ____ qui entrent comme Acétyl‑CoA directement dans le cycle du citrate. Dans nos cellules musculaires cela produit de l’acide lactique, dans les levures de l’éthanol et ____.",
