 "In den Unterlagen wurde kein lesbarer Text gefunden. Versuche schärfere Fotos oder eine andere Datei.": "Aucun texte lisible trouvé dans les documents. Essaie des photos plus nettes ou un autre fichier.",
 "In dieser Lektion sind alle Bausteine abgewählt. Schalte im Strategy Room Lernmethoden ein.": "Dans cette leçon, tous les blocs sont désactivés. Active les méthodes d’apprentissage dans le Strategy Room.",
 "In eigenen Worten, von Brainy bewertet": "En tes propres mots, évalué par Brainy",
 "In unseren Muskelzellen entsteht auf diese Weise Milchsäure, in Hefezellen entstehen Ethanol und Kohlenstoffdioxid.": "Dans nos cellules musculaires cela produit de l’acide lactique, dans les levures de l’éthanol et du dioxyde de carbone.",
 "Jede lebende Zelle muss ständig arbeiten.": "Chaque cellule vivante doit constamment travailler.",
 "Jede lebende Zelle muss ständig arbeiten. Sie baut Eiweisse auf, transportiert Stoffe durch ihre Membran, teilt sich und hält ihre Struktur aufrecht. Für alle diese Vorgänge benötigt sie Energie in einer Form, die sofort verfügbar ist. Diese Form ist das Molekül ATP, die Abkürzung für Adenosintriphosphat.": "Chaque cellule vivante doit constamment travailler. Elle synthétise des protéines, transporte des substances à travers sa membrane, se divise et maintient sa structure. Pour toutes ces actions, elle a besoin d’énergie immédiatement disponible : la molécule ATP, abréviation d’adénosine triphosphate.",
 "Jeden Schritt eingeben und prüfen": "Saisis chaque étape et vérifie",
