 "Keine Antwort. Richtig wäre: A) Dabei wird ein Molekül Glucose mit sechs Kohlenstoffatomen in zwei Moleküle Pyruvat mit je drei Kohlenstoffatomen gespalten.": "Pas de réponse. La bonne était : A) Une molécule de glucose à six atomes de carbone se scinde en deux molécules de pyruvate à trois atomes de carbone chacune.",
 "Keine Antwort. Richtig wäre: A) a": "Pas de réponse. La bonne était : A) a",
