 "Keine Antwort. Richtig wäre: C) c": "Pas de réponse. La bonne était : C) c",
 "Keine Antwort. Richtig wäre: D) Das Kohlenstoffdioxid, das wir ausatmen, stammt also aus der oxidativen Decarboxylierung und aus dem Citratzyklus.": "Pas de réponse. La bonne était : D) Le dioxyde de carbone que nous expirons provient donc de la décarboxylation oxydative et du cycle de l’acide citrique.",
 "Keine Antwort. Richtig wäre: D) Die Atmungskette besteht aus mehreren Proteinkomplexen, durch die Elektronen wie über Treppenstufen weitergereicht werden.": "Pas de réponse. La bonne était : D) La chaîne respiratoire est composée de plusieurs complexes protéiques, par lesquels les électrons sont transmis comme sur des marches d’escalier.",
 "Keine Antwort. Richtig wäre: D) Ein Molekül Glucose reagiert mit sechs Molekülen Sauerstoff zu sechs Molekülen Kohlenstoffdioxid und sechs Molekülen Wasser.": "Pas de réponse. La bonne était : D) Une molécule de glucose réagit avec six molécules d’oxygène pour former six molécules de dioxyde de carbone et six molécules d’eau.",
