 "Richtig wäre: #: ATP-Synthase · #: Sauerstoff": "Correct serait : #: ATP-synthase · #: Oxygène",
 "Richtig wäre: #: Acetyl-CoA · #: Atmungskette": "Correct serait : #: Acétyl‑CoA · #: Chaîne respiratoire",
