 "Richtig wären: A) a · C) c": "Correct seraient : A) a · C) c",
 "Richtig wären: B) Das Kohlenstoffdioxid, das wir ausatmen, stammt also aus der oxidativen Decarboxylierung und aus dem Citratzyklus. · D) Die Atmungskette besteht aus mehreren Proteinkomplexen, durch die Elektronen wie über Treppenstufen weitergereicht werden.": "Correct seraient : B) Le dioxyde de carbone que nous expirons provient donc de la décarboxylation oxydative et du cycle de l’acide citrique. · D) La chaîne respiratoire est composée de plusieurs complexes protéiques, par lesquels les électrons sont transmis comme sur des marches.",
 "Richtig – so steht es im Text.": "Correct – tel que dans le texte.",
 "Richtig: «": "Correct : «",
 "Richtig: «Energie» – so steht es im Text.": "Correct : «Énergie» – tel que dans le texte.",
 "Richtig: «Zellatmung» – so steht es im Text.": "Correct : «Respiration cellulaire» – tel que dans le texte.",
 "Richtige Reihenfolge": "Ordre correct",
 "Richtige Reihenfolge: #. Diese Membran ist stark gefaltet, die Falten heissen Cristae. · #. Die frei werdende Energie wird genutzt, um Protonen aus der Matrix in den Intermembranraum zu pumpen. · #. Sauerstoff ist also der letzte Elektronenakzeptor. · #. Wenn kein Sauerstoff vorhanden ist, kann die Zelle die Atmungskette nicht betreiben.": "Ordre correct : #. Cette membrane est fortement repliée, les replis s’appellent des cristae. · #. L’énergie libérée sert à pomper des protons de la matrice vers l’espace intermembranaire. · #. L’oxygène est donc le dernier accepteur d’électrons. · #. Sans oxygène, la cellule ne peut pas faire fonctionner la chaîne respiratoire.",
 "Richtige Reihenfolge: #. Dieser Schritt heisst oxidative Decarboxylierung. · #. Zuerst verbindet sich das Acetyl-CoA mit dem Molekül Oxalacetat zu Citrat, das Citrat hat sechs Kohlenstoffatome. · #. Weil aus einer Glucose zwei Acetyl-CoA entstehen, läuft der Zyklus pro Glucose zweimal. · #. Die Atmungskette sitzt in der inneren Membran der Mitochondrien.": "Ordre correct : #. Cette étape s’appelle décarboxylation oxydative. · #. D’abord l’Acétyl‑CoA se combine avec l’oxaloacétate pour former le citrate, qui possède six atomes de carbone. · #. Comme une glucose donne deux Acétyl‑CoA, le cycle tourne deux fois par glucose. · #. La chaîne respiratoire se trouve dans la membrane interne des mitochondries.",
 "Richtige Reihenfolge: #. Jede lebende Zelle muss ständig arbeiten. · #. ATP wirkt wie eine kleine, aufladbare Batterie der Zelle. · #. Den schrittweisen Abbau der Glucose unter Verwendung von Sauerstoff nennt man Zellatmung. · #. Dabei wird Energie freigesetzt, und ein Teil davon wird in ATP gespeichert.": "Ordre correct : #. Chaque cellule vivante doit travailler en permanence. · #. L’ATP agit comme une petite batterie rechargeable de la cellule. · #. La dégradation progressive du glucose avec oxygène s’appelle respiration cellulaire. · #. De l’énergie est libérée et une partie est stockée sous forme d’ATP.",
 "Richtige Reihenfolge: #. So wird die Energie in kleinen Portionen frei und kann gezielt in ATP umgewandelt werden. · #. Zuerst muss die Zelle selbst zwei ATP einsetzen, um die Glucose zu aktivieren. · #. Die Glykolyse braucht keinen Sauerstoff. · #. Der übrig bleibende Rest mit zwei Kohlenstoffatomen verbindet sich mit dem Coenzym A zum Acetyl-CoA.": "Ordre correct : #. L’énergie est libérée en petites portions et peut être convertie en ATP. · #. La cellule doit d’abord investir deux ATP pour activer le glucose. · #. La glycolyse ne nécessite pas d’oxygène. · #. Le résidu restant à deux carbones se combine avec la coenzyme A pour former l’Acétyl‑CoA.",
 "Richtige Reihenfolge: #. erst · #. dann · #. danach · #. zuletzt": "Ordre correct : #. d’abord · #. puis · #. ensuite · #. enfin",
