 "Starte mit einem Skript, Fotos deiner Notizen oder einem eingefügten Text.": "Commence avec un script, des photos de tes notes ou un texte inséré.",
 "Stattdessen zerlegt die Zelle den Zucker in vier aufeinanderfolgenden Abschnitten: die Glykolyse, die oxidative Decarboxylierung, der Citratzyklus und die Atmungskette.": "Au lieu de cela, la cellule décompose le sucre en quatre étapes successives : la glycolyse, la décarboxylation oxydative, le cycle du citrate et la chaîne respiratoire.",
 "Stattdessen zerlegt die Zelle den Zucker in vier aufeinanderfolgenden Abschnitten: die Glykolyse, die oxidative Kohlenstoffatomen, der Citratzyklus und die Atmungskette.": "Au lieu de cela, la cellule décompose le sucre en quatre étapes successives : la glycolyse, les atomes de carbone oxydatifs, le cycle du citrate et la chaîne respiratoire.",
 "Stattdessen zerlegt die Zelle den Zucker in vier aufeinanderfolgenden Abschnitten: die Glykolyse, die oxidative Kohlenstoffdioxid, der Citratzyklus und die Atmungskette.": "Au lieu de cela, la cellule décompose le sucre en quatre étapes successives : la glycolyse, le dioxyde de carbone oxydatif, le cycle du citrate et la chaîne respiratoire.",
 "Stattdessen zerlegt die Zelle den Zucker in vier aufeinanderfolgenden Abschnitten: die Glykolyse, die oxidative Stoffwechselweg, der Citratzyklus und die Atmungskette.": "Au lieu de cela, la cellule décompose le sucre en quatre étapes successives : la glycolyse, le chemin métabolique oxydatif, le cycle du citrate et la chaîne respiratoire.",
 "Stattdessen zerlegt die Zelle den Zucker in vier aufeinanderfolgenden Abschnitten: die Glykolyse, die oxidative …, der Citratzyklus…": "Au lieu de cela, la cellule décompose le sucre en quatre étapes successives : la glycolyse, l’oxydatif …, le cycle du citrate…",
 "Stattdessen zerlegt die Zelle den Zucker in vier aufeinanderfolgenden Abschnitten: die Gl…": "Au lieu de cela, la cellule décompose le sucre en quatre étapes successives : la Gl…",
