 "Würde die Glucose auf einmal verbrennen, entstünde ein Wärmeblitz, den die Zelle nicht nutzen könnte.": "Si le glucose était brûlé d’un coup, il y aurait une rafale de chaleur que la cellule ne pourrait pas exploiter.",
 "Würde die Glucose auf einmal verbrennen, entstünde ein Wärmeblitz, den die Zelle nicht nutzen könnte. Stattdessen zerlegt die Zelle den Zucker in vier aufeinanderfolgenden Abschnitten: die Glykolyse, die oxidative Decarboxylierung, der Citratzyklus und die Atmungskette. So wird die Energie in kleinen Portionen frei und kann gezielt in ATP umgewandelt werden.": "Si le glucose était brûlé d’un coup, il y aurait une rafale de chaleur que la cellule ne pourrait pas exploiter. Au lieu de cela, la cellule décompose le sucre en quatre étapes successives : la glycolyse, la décarboxylation oxydative, le cycle du citrate et la chaîne respiratoire. Ainsi, l’énergie est libérée en petites portions et peut être convertie ciblée en ATP.",
