 "window.Capacitor.Plugins.TextToSpeech": "window.Capacitor.Plugins.TextToSpeech",
 "z. B. Biologie Zellen": "p. ex. cellules de biologie",
 "zuletzt": "dernier",
 "zwei": "deux",
 "«Am Ende der Kette nimmt Sauerstoff die Elektronen und Protonen auf und bildet damit Wasser.» ist richtig; «In unseren Muskelzellen entsteht auf diese Weise Milchsäure, in Hefezellen entstehen Ethanol und Stoffwechselweg.» ist falsch; «Wenn eine Phosphatgruppe von ATP abgespalten wird, entsteht ADP, und dabei wird Energie frei, die die Zelle für ihre Arbeit nutzen kann.» ist richtig.": "«À la fin de la chaîne, l’oxygène capte les électrons et les protons et forme de l’eau.» est correct ; «Dans nos cellules musculaires, cela crée de l’acide lactique, dans les levures cela crée de l’éthanol et un chemin métabolique.» est faux ; «Quand un groupe phosphate est détaché de l’ATP, on obtient de l’ADP et de l’énergie que la cellule utilise pour travailler.» est correct.",
 "«Aussage eins» ist richtig; «Aussage zwei» ist falsch.": "«Affirmation un» est correcte ; «Affirmation deux» est fausse.",
 "«Aussage zwei» ist falsch.": "«Affirmation deux» est fausse.",
 "«Coenzym» passt hier nicht; im Text steht an dieser Stelle «Energie».": "«Coenzyme» ne convient pas ici ; le texte indique «Énergie».",
 "«Fehlerkurs» löschen?": "Supprimer «cours d’erreur» ?",
 "«Mengen» passt hier nicht; im Text steht an dieser Stelle «Energie».": "«Quantités» ne convient pas ici ; le texte indique «Énergie».",
 "«Molekül» passt hier nicht; im Text steht an dieser Stelle «Energie».": "«Molécule» ne convient pas ici ; le texte indique «Énergie».",
 "«Oxalacetat» passt hier nicht; im Text steht an dieser Stelle «Zellatmung».": "«Oxaloacétate» ne convient pas ici ; le texte indique «Respiration cellulaire».",
