 "#. ATP wirkt wie eine kleine, aufladbare Batterie der Zelle.": "#. L’ATP agit comme une petite batterie rechargeable de la cellule.",
 "#. Dabei wird Energie freigesetzt, und ein Teil davon wird in ATP gespeichert.": "#. L’énergie est libérée, et une partie est stockée dans l’ATP.",
 "#. Den schrittweisen Abbau der Glucose unter Verwendung von Sauerstoff nennt man Zellatmung.": "#. La dégradation progressive du glucose avec oxygène s’appelle respiration cellulaire.",
