 "ATP wirkt wie eine kleine, aufladbare Batterie der Zelle.": "L’ATP agit comme une petite batterie rechargeable de la cellule.",
 "ATP wirkt wie eine kleine, aufladbare Batterie der Zelle. Wenn eine Phosphatgruppe von ATP abgespalten wird, entsteht ADP, und dabei wird Energie frei, die die Zelle für ihre Arbeit nutzen kann. Die Zelle kann ATP nicht in grossen Mengen lagern. Deshalb muss sie ATP laufend neu herstellen, indem sie energiereiche Nährstoffe abbaut.": "L’ATP agit comme une petite batterie rechargeable de la cellule. Quand un groupe phosphate est détaché de l’ATP, il se forme de l’ADP et de l’énergie libérée que la cellule utilise pour son travail. La cellule ne peut pas stocker l’ATP en grande quantité. Elle doit donc le reconstituer continuellement en dégradant des nutriments riches en énergie.",
