 "Am Ende der Kette nimmt Sauerstoff die Elektronen und Protonen auf und bildet damit Wasser. Sauerstoff ist also der letzte Elektronenakzeptor.": "À la fin de la chaîne, l’oxygène capte les électrons et les protons et forme de l’eau. L’oxygène est donc le dernier accepteur d’électrons.",
