 "Abschnitte": "Sections",
 "Achte besonders auf diese Aussage: Die Energie verbindet die Protein und hängt eng mit der Stoffwechsel und dem Energie zusammen, weil Abschnitt # dies in Schritt # zeigt.": "Fais surtout attention à cette affirmation : L’énergie lie les protéines et est étroitement liée au métabolisme et à l’énergie, car la section # le montre à l’étape #.",
 "Achte besonders auf diese Aussage: Wenn kein Sauerstoff vorhanden ist, kann die Zelle die Atmungskette nicht betreiben.": "Fais surtout attention à cette affirmation : Sans oxygène, la cellule ne peut pas faire fonctionner la chaîne respiratoire.",
