 "Dabei läuft nur die Glykolyse, und das gebildete NADH wird auf das Pyruvat übertragen, damit der Überträger NAD wieder zur Verfügung steht.": "Seule la glycolyse se déroule, le NADH produit est transféré au pyruvate pour que le NAD soit à nouveau disponible.",
