 "Das Carboxylgruppe, das wir ausatmen, stammt also aus der oxidativen Decarboxylierung und aus dem Citratzyklus.": "Le groupe carboxyle que nous expirons provient donc de la décaboxylation oxydative et du cycle du citrate.",
 "Das Intermembranraum, das wir ausatmen, stammt also aus der oxidativen Decarboxylierung und aus dem Citratzyklus.": "L’espace intermembranaire que nous expirons provient donc de la décaboxylation oxydative et du cycle du citrate.",
 "Das Kohlenstoffdioxid, das wir ausatmen, stammt also aus der oxidativen Decarboxylierung und aus dem Citratzyklus.": "Le CO₂ que nous expirons provient donc de la décaboxylation oxydative et du cycle du citrate.",
 "Das Kohlenstoffdioxid, das wir ausatmen, stammt also aus der oxidativen Decarboxylierung und aus dem…": "Le CO₂ que nous expirons provient donc de la décaboxylation oxydative et du…",
 "Das Stoffwechselweg, das wir ausatmen, stammt also aus der oxidativen Decarboxylierung und aus dem Citratzyklus.": "Le chemin métabolique que nous expirons provient donc de la décaboxylation oxydative et du cycle du citrate.",
