 "Der Druck gibt an, wie stark eine Kraft auf eine": "La pression indique à quel point une force agit sur une",
 "Der Druck gibt an, wie stark eine Kraft auf eine bestimmte Fläche wirkt. Dieselbe Kraft erzeugt auf einer kleinen Fläche einen grossen Druck und auf einer grossen Fläche einen kleinen Druck. Der Druck ist der Quotient aus Kraft und Fläche.": "La pression indique à quel point une force agit sur une surface donnée. La même force crée une forte pression sur une petite surface et une faible pression sur une grande surface. La pression est le quotient de la force par la surface.",
 "Der Druck gibt an, wie stark eine Kraft auf eine bestimmte Fläche wirkt. Dieselbe Kraft erzeugt auf einer kleinen Fläche einen grossen Druck und auf einer grossen Fläche einen kleinen Druck. Deshalb sinkt man mit Schuhen im Schnee tiefer ein als mit breiten Skiern. Der Druck ist der Quotient aus Kraft und Fläche.": "La pression indique à quel point une force agit sur une surface donnée. La même force crée une forte pression sur une petite surface et une faible pression sur une grande surface. Ainsi, on s’enfonce plus avec des chaussures dans la neige qu’avec de larges skis. La pression est le quotient de la force par la surface.",
