 "Hintergrund. Hintergrund in deiner Avatar-Scheibe, für alle sichtbar.": "Contexte. Contexte dans ton cercle d'avatar, visible pour tous.",
 "IN": "EN",
 "Im Alltag gibt man sie meistens in … pro Stunde an, in der Physik rechnet man häufig mit Metern pro Sekunde.": "Dans la vie quotidienne, on les indique généralement en … par heure, en physique on calcule souvent en mètres par seconde.",
 "In": "En",
 "In der Physik wird Arbeit verrichtet, wenn eine Kraft einen Körper über eine Strecke bewegt.": "En physique, du travail est effectué lorsqu'une force déplace un corps sur une distance.",
 "In der Physik wird Arbeit verrichtet, wenn eine Kraft einen Körper über eine Strecke bewegt. Wer eine Kiste nur festhält, ohne sie zu bewegen, verrichtet im physikalischen Sinn keine Arbeit. Die Arbeit ist umso grösser, je grösser die Kraft und je länger der Weg ist. Gemessen wird sie in Joule.": "En physique, du travail est effectué lorsqu'une force déplace un corps sur une distance. Qui ne fait que tenir une caisse sans la bouger ne fait aucun travail au sens physique. Le travail augmente avec la force et la distance. Il se mesure en joules.",
 "In der Physik wird Arbeit …, wenn eine Kraft einen Körper über eine Strecke bewegt.": "En physique, du travail … lorsqu'une force déplace un corps sur une distance.",
 "In unseren Muskelzellen entsteht auf diese Weise Milchsäure, in Hefezellen entstehen Ethanol und…": "Dans nos cellules musculaires, on produit ainsi de l'acide lactique, dans les levures on produit de l'éthanol…",
