 "Je": "Je",
 "Je grösser die Masse eines Körpers ist, desto mehr Kraft braucht man, um seine Geschwindigkeit zu ändern. Der Druck gibt an, wie stark eine Kraft auf eine bestimmte Fläche wirkt. Dieselbe Kraft erzeugt auf einer kleinen Fläche einen grossen Druck und auf einer grossen Fläche einen kleinen Druck. Der Druck ist der Quotient aus Kraft und Fläche.": "Plus la masse d'un corps est grande, plus il faut de force pour changer sa vitesse. La pression indique la force exercée sur une surface donnée. La même force crée une forte pression sur une petite surface et une faible pression sur une grande surface. La pression est le quotient de la force par la surface.",
 "Je grösser die Masse eines Körpers ist, desto mehr Kraft braucht man, um seine Geschwindigkeit zu ändern. Dieselbe Kraft erzeugt auf einer kleinen Fläche einen grossen Druck und auf einer grossen Fläche einen kleinen Druck.": "Plus la masse d'un corps est grande, plus il faut de force pour changer sa vitesse. La même force crée une forte pression sur une petite surface et une faible pression sur une grande surface.",
