 "Setze zuerst in alle Lücken ein Wort ein.": "Mets d’abord un mot dans chaque espace.",
 "Siehe Basistext: Abschnitt # «Der Citratzyklus in der Matrix» – «Das Kohlenstoffdioxid, das wir ausatmen, stammt also aus der oxidativen Decarboxylierung und aus»": "Voir texte de base : section # «Le cycle de l’acide citrique dans la matrice» – «Le dioxyde de carbone que nous expirons provient donc de la décarboxylation oxydative et de…»",
 "Siehe Basistext: Abschnitt # «Der Citratzyklus in der Matrix» – «Sauerstoff wird in diesem Abschnitt noch nicht verbraucht, doch der Zyklus steht still, wenn die»": "Voir texte de base : section # «Le cycle de l’acide citrique dans la matrice» – «L’oxygène n’est pas encore consommé dans cette section, mais le cycle s’arrête quand…»",
 "Siehe Basistext: Abschnitt # «Dichte» – «Die Dichte beschreibt, wie viel Masse in einem bestimmten Volumen steckt.»": "Voir texte de base : section # «Densité» – «La densité décrit combien de masse se trouve dans un volume donné.»",
 "Siehe Basistext: Abschnitt # «Die Atmungskette an der inneren Membran» – «Die Atmungskette besteht aus mehreren Proteinkomplexen, durch die Elektronen wie über Treppenstufen»": "Voir texte de base : section # «La chaîne respiratoire sur la membrane interne» – «La chaîne respiratoire est composée de plusieurs complexes protéiques, par lesquels les électrons descendent comme sur des marches d’escalier»",
 "Siehe Basistext: Abschnitt # «Druck» – «$p = \\frac{F}{A}$ (p: Druck, F: Kraft, A: Fläche)»": "Voir texte de base : section # «Pression» – «$p = \\frac{F}{A}$ (p : pression, F : force, A : surface)»",
 "Siehe Basistext: Abschnitt # «Druck» – «Der Druck gibt an, wie stark eine Kraft auf eine bestimmte Fläche wirkt.»": "Voir texte de base : section # «Pression» – «La pression indique à quel point une force agit sur une surface donnée.»",
 "Siehe Basistext: Abschnitt # «Druck» – «Der Druck ist der Quotient aus Kraft und Fläche.»": "Voir texte de base : section # «Pression» – «La pression est le quotient de la force et de la surface.»",
 "Siehe Basistext: Abschnitt # «Druck» – «Dieselbe Kraft erzeugt auf einer kleinen Fläche einen grossen Druck und auf einer grossen Fläche»": "Voir texte de base : section # «Pression» – «La même force crée une forte pression sur une petite surface et une faible pression sur une grande surface»",
 "Siehe Basistext: Abschnitt # «Energie und Glucose im Überblick» – «Die Energie verbindet die Protein und hängt eng mit der Stoffwechsel und dem Energie zusammen, weil»": "Voir texte de base : section # «Énergie et glucose – aperçu» – «L’énergie lie les protéines et est étroitement liée au métabolisme et à l’énergie, parce que…»",
 "Siehe Basistext: Abschnitt # «Energie und Glucose im Überblick» – «Die Mitochondrium verbindet die Chromosom und hängt eng mit der Zelle und dem Chromosom zusammen,»": "Voir texte de base : section # «Énergie et glucose – aperçu» – «La mitochondrie relie le chromosome et est étroitement liée à la cellule et au chromosome,»",
 "Siehe Basistext: Abschnitt # «Geschwindigkeit» – «$v = \\frac{s}{t}$ (v: Geschwindigkeit, s: Strecke, t: Zeit)»": "Voir texte de base : section # «Vitesse» – «$v = \\frac{s}{t}$ (v : vitesse, s : distance, t : temps)»",
 "Siehe Basistext: Abschnitt # «Geschwindigkeit» – «Die Geschwindigkeit sagt, wie schnell sich ein Körper bewegt.»": "Voir texte de base : section # «Vitesse» – «La vitesse indique à quelle rapidité un corps se déplace.»",
 "Siehe Basistext: Abschnitt # «Kohlenstoffdioxid» – «Bei Aminosäuren wird zuerst die Aminogruppe abgespalten, der Rest tritt an verschiedenen Stellen in»": "Voir texte de base : section # «Dioxyde de carbone» – «Pour les acides aminés, le groupe amine est d’abord détaché, le reste intervient à différents endroits dans…»",
 "Siehe Basistext: Abschnitt # «Kohlenstoffdioxid» – «Fettsäuren werden in Stücke mit je zwei Kohlenstoffatomen zerlegt, die als Acetyl-CoA direkt in den»": "Voir texte de base : section # «Dioxyde de carbone» – «Les acides gras sont découpés en morceaux de deux atomes de carbone, qui deviennent de l’Acétyl‑CoA directement dans le…»",
 "Siehe Basistext: Abschnitt # «Kohlenstoffdioxid» – «In unseren Muskelzellen entsteht auf diese Weise Milchsäure, in Hefezellen entstehen Ethanol und»": "Voir texte de base : section # «Dioxyde de carbone» – «Dans nos cellules musculaires, cela produit de l’acide lactique, dans les levures on obtient de l’éthanol et…»",
 "Siehe Basistext: Abschnitt # «Kraft» – «Ein Newton beschleunigt eine Masse von einem Kilogramm in jeder Sekunde um einen Meter pro Sekunde.»": "Voir texte de base : section # «Force» – «Un newton accélère une masse d’un kilogramme chaque seconde d’un mètre par seconde.»",
 "Siehe Basistext: Abschnitt # «Kraft» – «Je grösser die Masse eines Körpers ist, desto mehr Kraft braucht man, um seine Geschwindigkeit zu»": "Voir texte de base : section # «Force» – «Plus la masse d’un corps est grande, plus il faut de force pour changer sa vitesse…»",
 "Siehe Basistext: Abschnitt # «Membran und Gen im Überblick» – «Die Ribosom liefert die Allel und hängt eng mit der Stoffwechsel und dem Vererbung zusammen, weil»": "Voir texte de base : section # «Membrane et gène – aperçu» – «Le ribosome fournit l’allèle et est étroitement lié au métabolisme et à l’hérédité, parce que…»",
 "Siehe Basistext: Abschnitt # «Membran und Gen im Überblick» – «Die Stoffwechsel baut ab die Muskel und hängt eng mit der Chromosom und dem Ribosom zusammen, weil»": "Voir texte de base : section # «Membrane et gène – aperçu» – «Le métabolisme décompose le muscle et est étroitement lié au chromosome et au ribosome, parce que…»",
