 "Welches Wort passt in die Lücke? «In unseren Muskelzellen entsteht auf diese Weise Milchsäure, in Hefezellen entstehen Ethanol und ___.»": "Quel mot complète la phrase ? «Dans nos cellules musculaires, on produit ainsi de l’acide lactique, dans les levures on obtient de l’éthanol et ___.»",
