 "✓ Richtig: Der Druck gibt an, wie stark eine Kraft auf eine bestimmte Fläche wirkt.": "✓ Correct : La pression indique à quel point une force agit sur une surface donnée.",
 "✓ Richtig: Je grösser die Masse eines Körpers ist, desto mehr Kraft braucht man, um seine Geschwindigkeit zu ändern.": "✓ Correct : Plus la masse d’un corps est grande, plus il faut de force pour changer sa vitesse.",
 "✗ Falsch: Dieselbe Kraft hundert auf einer kleinen Fläche einen grossen Druck und auf einer grossen Fläche einen kleinen Druck.": "✗ Faux : La même force crée une forte pression sur une petite surface et une faible pression sur une grande surface.",
 "Energie und Glucose im Überblick": "Énergie et glucose en aperçu",
 "Energie und Glucose im Überblick (Teil # von #)": "Énergie et glucose en aperçu (Partie # sur #)",
 "Energie und Glucose im Überblick (Teil # von #), Offen. Etappe öffnen": "Énergie et glucose en aperçu (Partie # sur #), Ouvert. Ouvrir l’étape",
 "Energie und Glucose im Überblick (Teil # von #), Sitzt sicher. Etappe öffnen": "Énergie et glucose en aperçu (Partie # sur #), En place. Ouvrir l’étape",
 "Fettsäuren werden in Stücke mit je zwei Wasserstoffatome zerlegt, die als Acetyl-CoA direkt in den Citratzyklus eintreten.": "Les acides gras sont découpés en morceaux de deux atomes d’hydrogène, qui entrent comme Acetyl‑CoA directement dans le cycle de l’acide citrique.",
 "Nora": "Nora",
 "Nur einmal pro Woche · Tagesgeschenk, einmal pro Tag": "Une fois par semaine · Cadeau du jour, une fois par jour",
 "Pro ist abgelaufen – deine Pro-Teile wurden abgelegt": "Pro est expiré – tes parties Pro ont été archivées",
 "Skin der Woche: Eis-Gehirn": "Skin de la semaine : Cerveau de glace",
 "Zoé": "Zoé",
 "der Freund": "l’ami",
 "l'ami": "l'ami",
