 "Eine Kraft kann einen Körper beschleunigen, abbremsen oder verformen. Je grösser die Masse eines Körpers ist, desto mehr Kraft braucht man, um seine Geschwindigkeit zu ändern. Die Einheit der Kraft ist das Newton. Ein Newton beschleunigt eine Masse von einem Kilogramm in jeder Sekunde um einen Meter pro Sekunde.": "Une force peut accélérer, ralentir ou déformer un corps. Plus la masse d'un corps est grande, plus il faut de force pour changer sa vitesse. L'unité de force est le Newton. Un Newton accélère une masse d'un kilogramme chaque seconde d'un mètre par seconde.",
